// Bulgarian content names (lane B owns this table; lane A seeded the core goods, tools, buildings, homes, animals,
// debris and townsfolk from docs/agent-briefs/i18n-glossary-bg.md). Keyed by content id; 'family:id' overrides an id
// that two families share (recipes share their item's id and need no entry of their own; 'features:<id>' are the
// feature names, 'restoration:farmhouse' Grandma's farmhouse as a Restoration project). Loaded only when Bulgarian is
// chosen (i18n/names.js). Shape and forms: see the header of i18n/names.js. The key scheme for the other content
// tables (wardrobe, looks, pets, medals, finds...) is in docs/agent-notes/i18n-names-league.md.
//   name   label form (titles, buttons), sentence case: 'Морков', 'Фуражна мелница'
//   g      'm' | 'f' | 'n' | 'pl'            pl / count / def / defObj / plDef: the forms (see the glossary)
//   short  the toolbar / chip label (max 8-14 characters)    lc: the in-sentence form when not just a lower-case first
//   letter (proper names keep their capital: 'баба Хейзъл')   one: the singular when the label is a plural ('Бурени')
//   unit   [after 1, after any other number] for a mass noun: ['сноп', 'снопа'] -> "1 сноп пшеница", "5 снопа пшеница"
//   desc   the description, when the content has one (ctext(family, id, 'desc', def.text))
const m = (name, pl, count, def, defObj, plDef, extra = {}) => ({ name, g: 'm', pl, count, def, defObj, plDef, ...extra });
const f = (name, pl, def, plDef, extra = {}) => ({ name, g: 'f', pl, def, plDef, ...extra });
const n = (name, pl, def, plDef, extra = {}) => ({ name, g: 'n', pl, def, plDef, ...extra });
const mass = (name, g, def, unit, extra = {}) => ({ name, g, def, unit, ...extra });
/** A name with no plural (a ribbon, a feature): a proper name (keeps its capital in a sentence), def / defObj only. */
const one = (name, g, def, defObj, extra = {}) => ({ name, g, proper: true, ...(def ? { def } : {}), ...(defObj ? { defObj } : {}), ...extra });
/** A name that is a plural ("Палачинки"): `one` is the singular after 1. */
const plural = (name, one, def, extra = {}) => ({ name, g: 'pl', pl: name[0].toLocaleLowerCase('bg') + name.slice(1), one, def, plDef: def, ...extra });
/** A masculine "<head> <tail>" whose tail never changes ("Мъфин с моркови"): head forms [pl, count, def, defObj, plDef]. */
const mt = (head, [pl, count, def, defObj, plDef], tail, extra = {}) =>
  m(`${head} ${tail}`, `${pl} ${tail}`, `${count} ${tail}`, `${def} ${tail}`, `${defObj} ${tail}`, `${plDef} ${tail}`, extra);
/** A town souvenir: "Сувенир от <place>". */
const souvenir = (place) => mt('Сувенир', ['сувенири', 'сувенира', 'сувенирът', 'сувенира', 'сувенирите'], `от ${place}`, { short: 'Сувенир' });
/** A place name that is already definite ("Ливадата край потока"): the same words in every form. */
const place = (name, g, extra = {}) => {
  const lc = name[0].toLocaleLowerCase('bg') + name.slice(1);
  return { name, g, def: lc, defObj: lc, plDef: lc, pl: lc, count: lc, ...extra };
};

